document.addEventListener('DOMContentLoaded',()=>{Overture.configure({assetBase:'assets/'});const names={stage:'暗场',paper:'印纸',nocturne:'夜场'},tb=document.getElementById('theme'),label=()=>{const O=Overture,now=document.documentElement.dataset.theme||'stage';tb.textContent=`主题：${names[now]} → ${names[O.themes[(O.themes.indexOf(now)+1)%O.themes.length]]}`;};label();tb.addEventListener('click',()=>{Overture.nextTheme();label();});const composer=Overture.mount('BrandComposer','#composer');window.addEventListener('pagehide',()=>composer.destroy(),{once:true});});
